import { readFileSync } from 'node:fs';
export type Missing = 'listwise' | 'mean';
export type Scaling = 'covariance' | 'correlation';
export type Criterion = 'kaiser' | 'broken_stick' | 'parallel' | 'cumulative';
export interface Row {
  id: string;
  values: (number | null)[];
}
export interface Settings {
  missing: Missing;
  scaling: Scaling;
  components: number | Criterion;
  target: number;
  parallel: number;
  seed: number;
  t2Limit: number;
  speLimit: number;
  cycles: number;
  top: number;
  screeWidth: number;
  biplotWidth: number;
  biplotHeight: number;
  radius: number;
  diagnosticWidth: number;
  diagnosticHeight: number;
}
export function readDataset() {
  const lines = (name: string) =>
    readFileSync('input/' + name, 'ascii')
      .slice(0, -1)
      .split('\n');
  const input = lines('data.csv');
  const names = input[0].split(',').slice(1);
  const rows = (input: string[]): Row[] =>
    input.slice(1).map((line) => {
      const [id, ...v] = line.split(',');
      return { id, values: v.map((x) => (x === 'NA' ? null : +x)) };
    });
  const parameters = new Map(
    lines('params.txt').map((line) => {
      const [k, ...v] = line.split(' ');
      return [k, v];
    }),
  );
  const p = (k: string) => parameters.get(k)!;
  const n = (k: string) => +p(k)[0];
  const rule = p('COMPONENTS')[0];
  const settings: Settings = {
    missing: p('MISSING')[0] as Missing,
    scaling: p('SCALING')[0] as Scaling,
    components: /^[0-9]+$/.test(rule) ? +rule : (rule as Criterion),
    target: n('CUMULATIVE_TARGET'),
    parallel: n('PARALLEL'),
    seed: +p('PARALLEL')[1],
    t2Limit: n('T2_LIMIT'),
    speLimit: n('SPE_LIMIT'),
    cycles: n('VARIMAX_CYCLES'),
    top: n('TOP_ROWS'),
    screeWidth: n('SCREE_WIDTH'),
    biplotWidth: n('BIPLOT_SIZE'),
    biplotHeight: +p('BIPLOT_SIZE')[1],
    radius: n('CIRCLE_RADIUS'),
    diagnosticWidth: n('DIAGNOSTIC_SIZE'),
    diagnosticHeight: +p('DIAGNOSTIC_SIZE')[1],
  };
  return { names, rows: rows(input), supplementary: rows(lines('supplementary.csv')), settings };
}
export type Dataset = ReturnType<typeof readDataset>;

import * as matrix from './matrix.ts';
export interface Eigensystem {
  values: number[];
  vectors: number[][];
  sweeps: number;
}
export function offDiagonal(m: number[][]): number {
  let total = 0;
  for (let p = 0; p < m.length - 1; p++) {
    for (let q = p + 1; q < m.length; q++) total += m[p][q] * m[p][q];
  }
  return total;
}
export function rotate(a: number[][], v: number[][], p: number, q: number): void {
  if (a[p][q] === 0) return;
  const theta = (a[q][q] - a[p][p]) / (2 * a[p][q]);
  let t = 1 / (Math.abs(theta) + Math.sqrt(theta * theta + 1));
  if (theta < 0) t = -t;
  const c = 1 / Math.sqrt(t * t + 1);
  const s = t * c;
  for (let r = 0; r < a.length; r++) {
    if (r !== p && r !== q) {
      const x = a[r][p];
      const y = a[r][q];
      a[r][p] = a[p][r] = c * x - s * y;
      a[r][q] = a[q][r] = s * x + c * y;
    }
  }
  const cross = a[p][q];
  a[p][p] -= t * cross;
  a[q][q] += t * cross;
  a[p][q] = a[q][p] = 0;
  for (const row of v) {
    const x = row[p];
    const y = row[q];
    row[p] = c * x - s * y;
    row[q] = s * x + c * y;
  }
}
export function jacobi(input: number[][]): Eigensystem {
  const a = matrix.copy(input);
  const v = matrix.identity(input.length);
  const initial = offDiagonal(a);
  let sweeps = 0;
  if (initial !== 0) {
    for (let sweep = 1; sweep <= 100; sweep++) {
      for (let p = 0; p < a.length - 1; p++) {
        for (let q = p + 1; q < a.length; q++) rotate(a, v, p, q);
      }
      const off = offDiagonal(a);
      if (!sweeps && off < 1e-16 * initial) sweeps = sweep;
      if (off < 1e-22 * initial) break;
    }
  }
  const order = input.map((_, i) => i).sort((a1, b) => a[b][b] - a[a1][a1] || a1 - b);
  return {
    values: order.map((k) => a[k][k]),
    vectors: order.map((k) => matrix.orient(matrix.normalize(matrix.column(v, k)))),
    sweeps,
  };
}
export function power(input: number[][], reference: Eigensystem) {
  const remaining = matrix.copy(input);
  return reference.values.map((lambda, k) => {
    let vector: number[] = Array(input.length).fill(1);
    let agreement: number | null = null;
    const target = reference.vectors[k];
    const negative = target.map((x) => -x);
    for (let t = 1; t <= 1000; t++) {
      vector = matrix.normalize(matrix.multiply(remaining, vector));
      if (
        agreement === null &&
        Math.min(matrix.difference(vector, target), matrix.difference(vector, negative)) < 0.000001
      ) {
        agreement = t;
      }
    }
    const value = matrix.dot(vector, matrix.multiply(remaining, vector));
    const oriented = matrix.orient(matrix.normalize(vector));
    const match =
      Math.abs(value - lambda) <= 1e-8 * reference.values[0] &&
      matrix.difference(oriented, target) <= 0.000001;
    matrix.deflate(remaining, value, oriented);
    return { value, vector: oriented, agreement, match };
  });
}

import { mkdirSync, writeFileSync } from 'node:fs';
import {
  readDataset,
  type Dataset,
  type Row,
  type Missing,
  type Scaling,
  type Settings,
} from './dataset.ts';
import * as matrix from './matrix.ts';
import * as eigen from './eigen.ts';
import * as pca from './pca.ts';
import * as plot from './plot.ts';

function real(v: number, digits = 4): string {
  if (Math.abs(v) >= 1e21) return BigInt(v).toString() + '.' + '0'.repeat(digits);
  const text = v.toFixed(digits);
  return +text === 0 ? (0).toFixed(digits) : text;
}
function reals(v: number[]): string {
  return v.map((x) => real(x)).join(' ');
}
function sum(v: number[]): number {
  let s = 0;
  for (const x of v) s += x;
  return s;
}
function sections(parts: string[][]): string[] {
  return parts.flatMap((p, i) => (i ? ['', ...p] : p));
}
function names(prefix: string, count: number): string[] {
  return Array.from({ length: count }, (_, i) => prefix + (i + 1));
}
function top<T>(items: T[], value: (item: T) => number, count: number): T[] {
  return items
    .map((item, index) => ({ item, index, value: value(item) }))
    .sort((a, b) => b.value - a.value || a.index - b.index)
    .slice(0, count)
    .map((e) => e.item);
}
function maximumIndex(v: number[]): number {
  let best = 0;
  for (let i = 1; i < v.length; i++) if (v[i] > v[best]) best = i;
  return best;
}
function summarize(data: Dataset) {
  return data.names.map((name, j) => {
    const observed = data.rows.map((r) => r.values[j]).filter((v): v is number => v !== null);
    const mean = sum(observed) / observed.length;
    return {
      name,
      observed: observed.length,
      missing: data.rows.length - observed.length,
      mean,
      deviation: Math.sqrt(
        sum(observed.map((v) => (v - mean) * (v - mean))) / (observed.length - 1),
      ),
      minimum: Math.min(...observed),
      maximum: Math.max(...observed),
    };
  });
}
function analysis(
  data: Dataset,
  summary: ReturnType<typeof summarize>,
  missing: Missing,
  scaling: Scaling,
) {
  const rows = data.rows
    .filter((r) => missing === 'mean' || !r.values.includes(null))
    .map((r) => ({ id: r.id, values: r.values.map((v, j) => (v === null ? summary[j].mean : v)) }));
  const prepared = pca.prepare(
    rows.map((r) => r.values),
    scaling,
  );
  return { rows, prepared, eigen: eigen.jacobi(prepared.matrix) };
}
type Analysis = ReturnType<typeof analysis>;
function adequacy(r: number[][], n: number) {
  const p = r.length;
  const { inverse, determinant } = matrix.inverseDeterminant(r);
  const rr: number[] = [];
  const pp: number[] = [];
  const msa: number[] = [];
  for (let j = 0; j < p; j++) {
    let a = 0;
    let b = 0;
    for (let k = 0; k < p; k++) {
      if (j !== k) {
        const partial = -inverse[j][k] / Math.sqrt(inverse[j][j] * inverse[k][k]);
        a += r[j][k] * r[j][k];
        b += partial * partial;
      }
    }
    rr.push(a);
    pp.push(b);
    msa.push(a / (a + b));
  }
  const total = sum(rr);
  return {
    msa,
    determinant,
    kmo: total / (total + sum(pp)),
    bartlett: -(n - 1 - (2 * p + 5) / 6) * Math.log(determinant),
    degrees: (p * (p - 1)) / 2,
  };
}
function parallelAnalysis(n: number, p: number, settings: Settings): number[] {
  let state = settings.seed;
  const totals: number[] = Array(p).fill(0);
  for (let r = 0; r < settings.parallel; r++) {
    const rows = matrix.zeros(n, p);
    for (const row of rows) {
      for (let j = 0; j < p; j++) {
        state = (48271 * state) % 2147483647;
        row[j] = state / 2147483647;
      }
    }
    const values = eigen.jacobi(pca.prepare(rows, 'correlation').correlation).values;
    const total = sum(values);
    for (let k = 0; k < p; k++) totals[k] += values[k] / total;
  }
  return totals.map((t) => t / settings.parallel);
}
function retention(values: number[], n: number, parallel: number[], settings: Settings) {
  const p = values.length;
  const total = sum(values);
  const average = total / p;
  const ratios = values.map((v) => v / total);
  const cumulative: number[] = [];
  let accumulated = 0;
  for (const r of ratios) {
    accumulated += r;
    cumulative.push(accumulated);
  }
  const broken = values.map((_, k) => {
    let s = 0;
    for (let i = k + 1; i <= p; i++) s += 1 / i;
    return s / p;
  });
  const errors = values.map((v) => v * Math.sqrt(2 / n));
  const separated = values.map(
    (v, k) =>
      (k === 0 || Math.abs(v - values[k - 1]) > errors[k]) &&
      (k === p - 1 || Math.abs(v - values[k + 1]) > errors[k]),
  );
  const leading = (bounds: number[]) => {
    const failed = ratios.findIndex((r, k) => r <= bounds[k]);
    return failed < 0 ? p : failed;
  };
  const criteria = {
    kaiser: values.filter((v) => v > average).length,
    broken_stick: leading(broken),
    parallel: leading(parallel),
    cumulative: cumulative.findIndex((v) => v >= settings.target) + 1,
  };
  return {
    total,
    average,
    ratios,
    cumulative,
    broken,
    parallel,
    errors,
    separated,
    criteria,
    retained: Math.max(
      1,
      typeof settings.components === 'number' ? settings.components : criteria[settings.components],
    ),
  };
}
function criterion(g: number[][]): number {
  const p = g.length;
  let total = 0;
  for (let k = 0; k < g[0].length; k++) {
    let q4 = 0;
    let q2 = 0;
    for (const row of g) {
      const v = row[k];
      q4 += v * v * (v * v);
      q2 += v * v;
    }
    total += q4 / p - (q2 / p) * (q2 / p);
  }
  return total;
}
function rotateVarimax(g: number[][], a: number, b: number): void {
  let sa = 0;
  let sb = 0;
  let sc = 0;
  let sd = 0;
  for (const row of g) {
    const phi = row[a] * row[a] - row[b] * row[b];
    const psi = 2 * row[a] * row[b];
    sa += phi;
    sb += psi;
    sc += phi * phi - psi * psi;
    sd += 2 * phi * psi;
  }
  const num = sd - (2 * sa * sb) / g.length;
  const den = sc - (sa * sa - sb * sb) / g.length;
  const omega = Math.sqrt(num * num + den * den);
  if (omega === 0) return;
  const cos4 = den / omega;
  const sin4 = num / omega;
  const cos2 = Math.sqrt((1 + cos4) / 2);
  const sin2 = cos2 === 0 ? 1 : sin4 / (2 * cos2);
  const cos1 = Math.sqrt((1 + cos2) / 2);
  const sin1 = sin2 / (2 * cos1);
  for (const row of g) {
    const x = row[a];
    const y = row[b];
    row[a] = cos1 * x + sin1 * y;
    row[b] = -sin1 * x + cos1 * y;
  }
}
function varimax(loadings: number[][], retained: number, cycles: number) {
  const eta = loadings.map((row) => Math.sqrt(sum(row.slice(0, retained).map((v) => v * v))));
  const normalized = loadings.map((row, j) => row.slice(0, retained).map((v) => v / eta[j]));
  const criteria = [criterion(normalized)];
  for (let c = 0; c < cycles; c++) {
    for (let a = 0; a < retained - 1; a++) {
      for (let b = a + 1; b < retained; b++) rotateVarimax(normalized, a, b);
    }
    criteria.push(criterion(normalized));
  }
  const columns = Array.from({ length: retained }, (_, index) => {
    const vector = matrix.orient(normalized.map((row, j) => row[index] * eta[j]));
    const agreements = Array.from({ length: retained }, (_, k) => {
      const original = matrix.column(loadings, k);
      return Math.abs(
        matrix.dot(vector, original) /
          Math.sqrt(matrix.dot(vector, vector) * matrix.dot(original, original)),
      );
    });
    const closest = maximumIndex(agreements);
    return {
      index,
      vector,
      square: matrix.dot(vector, vector),
      closest,
      congruence: agreements[closest],
    };
  }).sort((a, b) => b.square - a.square || a.index - b.index);
  return { criteria, columns };
}
function diagnostics(
  row: Row,
  z: number[],
  result: eigen.Eigensystem,
  retained: number,
  settings: Settings,
) {
  const scores = pca.scores(z, result.vectors);
  const residuals = pca.residuals(z, scores, result.vectors, retained);
  const t2 = pca.tSquared(scores, result.values, retained);
  const spe = matrix.dot(residuals, residuals);
  const flag = (t2 > settings.t2Limit ? 'T' : '') + (spe > settings.speLimit ? 'Q' : '');
  const t2Contributions = z.map((v, j) => {
    let w = 0;
    for (let k = 0; k < retained; k++) w += (scores[k] / result.values[k]) * result.vectors[k][j];
    return v * w;
  });
  return {
    row,
    standardized: z,
    scores,
    residuals,
    t2,
    spe,
    flag: flag || '-',
    quality: sum(scores.slice(0, retained).map((v) => v * v)) / matrix.dot(z, z),
    t2Contributions,
    speContributions: residuals.map((v) => v * v),
  };
}
type Diagnostic = ReturnType<typeof diagnostics>;
function supplementaryRows(data: Dataset, main: Analysis, k: number, training: Diagnostic[]) {
  return data.supplementary.map((row) => {
    const item = diagnostics(
      row,
      pca.standardize(row.values, main.prepared.means, main.prepared.scales),
      main.eigen,
      k,
      data.settings,
    );
    let nearest = 0;
    let distance = Infinity;
    training.forEach((other, i) => {
      let d = 0;
      for (let h = 0; h < k; h++) {
        const v = item.scores[h] - other.scores[h];
        d += v * v;
      }
      if (d < distance) {
        distance = d;
        nearest = i;
      }
    });
    return { ...item, nearest: training[nearest].row.id, distance: Math.sqrt(distance) };
  });
}
type Supplementary = ReturnType<typeof supplementaryRows>;
function scoreSummary(data: Dataset, main: Analysis, training: Diagnostic[], k: number): string[] {
  const lines = ['scores', 'component sd min min_id max max_id contributors'];
  for (let h = 0; h < k; h++) {
    let squared = 0;
    let min = training[0];
    let max = training[0];
    for (const item of training) {
      squared += item.scores[h] * item.scores[h];
      if (item.scores[h] < min.scores[h]) min = item;
      if (item.scores[h] > max.scores[h]) max = item;
    }
    const contributions = training.map((item) => ({
      id: item.row.id,
      value: (item.scores[h] * item.scores[h]) / ((training.length - 1) * main.eigen.values[h]),
    }));
    lines.push(
      `pc${h + 1} ${real(Math.sqrt(squared / (training.length - 1)))} ${real(min.scores[h])} ${min.row.id} ${real(max.scores[h])} ${max.row.id} ${top(
        contributions,
        (c) => c.value,
        data.settings.top,
      )
        .map((c) => c.id + ':' + real(c.value))
        .join(' ')}`,
    );
  }
  return lines;
}
function eigenReport(
  data: Dataset,
  summary: ReturnType<typeof summarize>,
  main: Analysis,
  measures: ReturnType<typeof adequacy>,
  r: ReturnType<typeof retention>,
  power: ReturnType<typeof eigen.power>,
  rotation: ReturnType<typeof varimax>,
  training: Diagnostic[],
): string[] {
  const s = data.settings;
  const p = data.names.length;
  const incomplete = data.rows.filter((row) => row.values.includes(null));
  const intro = [
    `pca rows ${data.rows.length} used ${main.rows.length} variables ${p} missing ${s.missing} scaling ${s.scaling}`,
    `incomplete ${incomplete.length} ${incomplete.length ? incomplete.map((row) => row.id).join(' ') : '-'}`,
  ];
  const variables = [
    'variable observed missing mean sd min max msa',
    ...summary.map(
      (v, j) =>
        `${v.name} ${v.observed} ${v.missing} ${reals([v.mean, v.deviation, v.minimum, v.maximum, measures.msa[j]])}`,
    ),
    `adequacy kmo ${real(measures.kmo)} determinant ${real(measures.determinant, 6)} bartlett ${real(measures.bartlett)} df ${measures.degrees}`,
  ];
  const pairs: { j: number; k: number; value: number }[] = [];
  for (let j = 0; j < p; j++) {
    for (let k = j + 1; k < p; k++) pairs.push({ j, k, value: main.prepared.correlation[j][k] });
  }
  const mat = [
    `matrix ${s.scaling}`,
    ...main.prepared.matrix.map((row, j) => `${data.names[j]} ${reals(row)}`),
    'strongest ' +
      top(pairs, (v) => Math.abs(v.value), s.top)
        .map((v) => `${data.names[v.j]}:${data.names[v.k]}:${real(v.value)}`)
        .join(' '),
  ];
  const spectrum = [
    `jacobi sweeps ${main.eigen.sweeps}`,
    `eigenvalues total ${real(r.total)} average ${real(r.average)}`,
    'k eigenvalue ratio cumulative broken_stick parallel se separated',
    ...main.eigen.values.map(
      (v, k) =>
        `${k + 1} ${reals([v, r.ratios[k], r.cumulative[k], r.broken[k], r.parallel[k], r.errors[k]])} ${r.separated[k] ? 'yes' : 'no'}`,
    ),
    `retention kaiser ${r.criteria.kaiser} broken_stick ${r.criteria.broken_stick} parallel ${r.criteria.parallel} cumulative ${r.criteria.cumulative} target ${real(s.target)}`,
    `components ${r.retained} rule ${s.components}`,
  ];
  const vectors = [
    'eigenvectors',
    'variable ' + names('pc', p).join(' '),
    ...data.names.map((name, j) => `${name} ${reals(main.eigen.vectors.map((v) => v[j]))}`),
  ];
  const cross = [
    'power_iteration iterations 1000',
    'k jacobi power agree_at match',
    ...power.map(
      (v, k) =>
        `${k + 1} ${real(main.eigen.values[k])} ${real(v.value)} ${v.agreement ?? '-'} ${v.match ? 'yes' : 'no'}`,
    ),
    `cross_check ${power.filter((v) => v.match).length}/${p}`,
  ];
  const rotated = [
    `varimax components ${r.retained} cycles ${s.cycles}`,
    ...rotation.criteria.map((v, c) => `cycle ${c} criterion ${real(v, 6)}`),
    ...rotation.columns.map(
      (v, k) =>
        `rc${k + 1} ss ${real(v.square)} ratio ${real(v.square / r.total)} closest pc${v.closest + 1} congruence ${real(v.congruence)}`,
    ),
  ];
  const sensitivity = [
    'sensitivity',
    'missing scaling rows sweeps eigenvalues cumulative congruence',
  ];
  for (const missing of ['listwise', 'mean'] as const) {
    for (const scaling of ['covariance', 'correlation'] as const) {
      const other = analysis(data, summary, missing, scaling);
      const total = sum(other.eigen.values);
      let cumulative = 0;
      const congruence: number[] = [];
      for (let k = 0; k < r.retained; k++) {
        cumulative += other.eigen.values[k] / total;
        congruence.push(Math.abs(matrix.dot(other.eigen.vectors[k], main.eigen.vectors[k])));
      }
      sensitivity.push(
        `${missing} ${scaling} ${other.rows.length} ${other.eigen.sweeps} ${reals(other.eigen.values.slice(0, r.retained))} ${real(cumulative)} ${reals(congruence)}`,
      );
    }
  }
  return sections([
    intro,
    variables,
    mat,
    spectrum,
    vectors,
    cross,
    scoreSummary(data, main, training, r.retained),
    rotated,
    sensitivity,
  ]);
}
function outlierReport(
  data: Dataset,
  main: Analysis,
  training: Diagnostic[],
  supplementary: Supplementary,
  k: number,
): string[] {
  const first = [
    `diagnostics components ${k} t2_limit ${real(data.settings.t2Limit)} spe_limit ${real(data.settings.speLimit)}`,
    'id t2 spe quality flag',
    ...training.map((v) => `${v.row.id} ${reals([v.t2, v.spe, v.quality])} ${v.flag}`),
    `flagged t2 ${training.filter((v) => v.flag.includes('T')).length} spe ${training.filter((v) => v.flag.includes('Q')).length} both ${training.filter((v) => v.flag === 'TQ').length} any ${training.filter((v) => v.flag !== '-').length}`,
  ];
  const parts = [first];
  for (const statistic of ['t2', 'spe'] as const) {
    parts.push([
      `top ${statistic}`,
      `rank id ${statistic} variable contribution`,
      ...top(training, (v) => v[statistic], data.settings.top).map((v, rank) => {
        const contributions = statistic === 't2' ? v.t2Contributions : v.speContributions;
        const j = maximumIndex(contributions);
        return `${rank + 1} ${v.row.id} ${real(v[statistic])} ${data.names[j]} ${real(contributions[j])}`;
      }),
    ]);
  }
  const reconstruction = ['reconstruction', 'k mean_spe max_spe max_id'];
  for (let h = 1; h < data.names.length; h++) {
    let total = 0;
    let maximum = -Infinity;
    let id = '';
    for (const v of training) {
      const errors = pca.residuals(v.standardized, v.scores, main.eigen.vectors, h);
      const spe = matrix.dot(errors, errors);
      total += spe;
      if (spe > maximum) {
        maximum = spe;
        id = v.row.id;
      }
    }
    reconstruction.push(`${h} ${real(total / training.length)} ${real(maximum)} ${id}`);
  }
  return sections([
    ...parts,
    reconstruction,
    [
      'supplementary',
      `id ${names('pc', k).join(' ')} t2 spe flag nearest distance`,
      ...supplementary.map(
        (v) =>
          `${v.row.id} ${reals(v.scores.slice(0, k))} ${reals([v.t2, v.spe])} ${v.flag} ${v.nearest} ${real(v.distance)}`,
      ),
    ],
  ]);
}
function axes(g: string[][], p: plot.Cell): void {
  g[p.row].fill('-');
  for (const row of g) row[p.column] = '|';
  g[p.row][p.column] = '+';
}
function density(g: string[][], positions: plot.Cell[]): void {
  const counts = matrix.zeros(g.length, g[0].length);
  for (const p of positions) counts[p.row][p.column]++;
  for (let r = 0; r < g.length; r++) {
    for (let c = 0; c < g[0].length; c++) {
      const n = counts[r][c];
      if (n > 0) g[r][c] = n === 1 ? '.' : n <= 3 ? 'o' : '@';
    }
  }
}
function plotsReport(
  data: Dataset,
  main: Analysis,
  retained: ReturnType<typeof retention>,
  training: Diagnostic[],
  supplementary: Supplementary,
  loadings: number[][],
): string[] {
  const s = data.settings;
  const largest = main.eigen.values[0];
  const kc = Math.floor((retained.average / largest) * s.screeWidth + 0.5);
  const scree = [
    `scree width ${s.screeWidth} kaiser_column ${kc}`,
    ...main.eigen.values.map(
      (v, k) =>
        `|${plot.scree(s.screeWidth, Math.floor((v / largest) * s.screeWidth + 0.5), Math.floor(((retained.broken[k] * retained.total) / largest) * s.screeWidth + 0.5), kc)}| pc${k + 1} ${real(v)}`,
    ),
  ];
  const all = [...training, ...supplementary];
  const mx = Math.max(...all.map((v) => Math.abs(v.scores[0])));
  const my = Math.max(...all.map((v) => Math.abs(v.scores[1])));
  const lx = Math.max(...loadings.map((v) => Math.abs(v[0])));
  const ly = Math.max(...loadings.map((v) => Math.abs(v[1])));
  const scale = 0.9 * Math.min(mx / lx, my / ly);
  const cell = (x: number, y: number) =>
    plot.biplotCell(x, y, mx, my, s.biplotWidth, s.biplotHeight);
  const origin = cell(0, 0);
  const b = plot.grid(s.biplotWidth, s.biplotHeight);
  axes(b, origin);
  const tips = loadings.map((v) => cell(scale * v[0], scale * v[1]));
  for (const tip of tips) for (const p of plot.shaft(origin, tip)) b[p.row][p.column] = p.character;
  const positions = training.map((v) => cell(v.scores[0], v.scores[1]));
  density(b, positions);
  training.forEach((v, i) => {
    if (v.flag !== '-') b[positions[i].row][positions[i].column] = 'X';
  });
  for (const v of supplementary) {
    const p = cell(v.scores[0], v.scores[1]);
    b[p.row][p.column] = '*';
  }
  tips.forEach((p, j) => {
    b[p.row][p.column] = String.fromCharCode(65 + j);
  });
  const biplot = [
    `biplot pc1 pc2 width ${s.biplotWidth} height ${s.biplotHeight}`,
    `x ${real(-mx)} ${real(mx)} y ${real(-my)} ${real(my)} arrow_scale ${real(scale)}`,
    ...plot.frame(b),
    ...data.names.map(
      (name, j) => `${String.fromCharCode(65 + j)} ${name} ${reals(loadings[j].slice(0, 2))}`,
    ),
  ];
  const rho = s.radius;
  const rc = rho / 2 + 1;
  const cc = rho + 1;
  const circle = plot.grid(2 * rho + 3, rho + 3);
  axes(circle, { row: rc, column: cc });
  const inside = (r: number, c: number) =>
    (c - cc) * (c - cc) + 2 * (r - rc) * (2 * (r - rc)) <= rho * rho;
  for (let r = 0; r < circle.length; r++) {
    for (let c = 0; c < circle[0].length; c++) {
      if (
        inside(r, c) &&
        (!inside(r - 1, c) || !inside(r + 1, c) || !inside(r, c - 1) || !inside(r, c + 1))
      ) {
        circle[r][c] = '.';
      }
    }
  }
  const correlations = loadings.map((v, j) =>
    v.slice(0, 2).map((x) => x / Math.sqrt(main.prepared.matrix[j][j])),
  );
  correlations.forEach((v, j) => {
    circle[rc - Math.floor(v[1] * (rho / 2) + 0.5)][cc + Math.floor(v[0] * rho + 0.5)] =
      String.fromCharCode(65 + j);
  });
  const circleLines = [
    `circle radius ${rho}`,
    ...plot.frame(circle),
    ...correlations.map(
      (v, j) =>
        `${String.fromCharCode(65 + j)} ${data.names[j]} ${reals([v[0], v[1], v[0] * v[0] + v[1] * v[1]])}`,
    ),
  ];
  const dx = 2 * s.t2Limit;
  const dy = 2 * s.speLimit;
  const dg = plot.grid(s.diagnosticWidth, s.diagnosticHeight);
  const pos = (v: Diagnostic) =>
    plot.diagnosticCell(v.t2, v.spe, dx, dy, s.diagnosticWidth, s.diagnosticHeight);
  axes(
    dg,
    plot.diagnosticCell(s.t2Limit, s.speLimit, dx, dy, s.diagnosticWidth, s.diagnosticHeight),
  );
  density(dg, training.map(pos));
  for (const v of supplementary) {
    const p = pos(v);
    dg[p.row][p.column] = '*';
  }
  return sections([
    scree,
    biplot,
    circleLines,
    [
      `diagnostic width ${s.diagnosticWidth} height ${s.diagnosticHeight} t2_max ${real(dx)} spe_max ${real(dy)}`,
      ...plot.frame(dg),
    ],
  ]);
}
function main(): void {
  const data = readDataset();
  const summary = summarize(data);
  const main = analysis(data, summary, data.settings.missing, data.settings.scaling);
  const measures = adequacy(main.prepared.correlation, main.rows.length);
  const retained = retention(
    main.eigen.values,
    main.rows.length,
    parallelAnalysis(main.rows.length, data.names.length, data.settings),
    data.settings,
  );
  const k = retained.retained;
  const loadings = data.names.map((_, j) =>
    main.eigen.values.map((v, h) => main.eigen.vectors[h][j] * Math.sqrt(v)),
  );
  const rotation = varimax(loadings, k, data.settings.cycles);
  const training = main.rows.map((row, i) =>
    diagnostics(row, main.prepared.standardized[i], main.eigen, k, data.settings),
  );
  const supplementary = supplementaryRows(data, main, k, training);
  const loadingLines = [
    ['variable', ...names('pc', k), 'communality', ...names('rc', k)].join(','),
    ...data.names.map((name, j) =>
      [
        name,
        ...loadings[j].slice(0, k).map((v) => real(v)),
        real(sum(loadings[j].slice(0, k).map((v) => v * v)) / main.prepared.matrix[j][j]),
        ...rotation.columns.map((v) => real(v.vector[j])),
      ].join(','),
    ),
  ];
  const scoreLines = [
    ['id', 'set', ...names('pc', k)].join(','),
    ...training.map((v) =>
      [v.row.id, 'data', ...v.scores.slice(0, k).map((x) => real(x))].join(','),
    ),
    ...supplementary.map((v) =>
      [v.row.id, 'supplementary', ...v.scores.slice(0, k).map((x) => real(x))].join(','),
    ),
  ];
  const reports: Record<string, string[]> = {
    'eigen.txt': eigenReport(
      data,
      summary,
      main,
      measures,
      retained,
      eigen.power(main.prepared.matrix, main.eigen),
      rotation,
      training,
    ),
    'loadings.csv': loadingLines,
    'scores.csv': scoreLines,
    'outliers.txt': outlierReport(data, main, training, supplementary, k),
    'plots.txt': plotsReport(data, main, retained, training, supplementary, loadings),
  };
  mkdirSync('output', { recursive: true });
  for (const [name, lines] of Object.entries(reports)) {
    writeFileSync('output/' + name, lines.join('\n') + '\n', 'ascii');
  }
}
main();

export function zeros(rows: number, columns = rows): number[][] {
  return Array.from({ length: rows }, () => Array(columns).fill(0));
}
export function identity(size: number): number[][] {
  const m = zeros(size);
  for (let i = 0; i < size; i++) m[i][i] = 1;
  return m;
}
export function copy(m: number[][]): number[][] {
  return m.map((row) => [...row]);
}
export function column(m: number[][], k: number): number[] {
  return m.map((row) => row[k]);
}
export function dot(a: number[], b: number[]): number {
  let total = 0;
  for (let i = 0; i < a.length; i++) total += a[i] * b[i];
  return total;
}
export function multiply(m: number[][], v: number[]): number[] {
  return m.map((row) => dot(row, v));
}
export function length(v: number[]): number {
  return Math.sqrt(dot(v, v));
}
export function normalize(v: number[]): number[] {
  const n = length(v);
  return v.map((x) => x / n);
}
export function orient(v: number[]): number[] {
  let k = 0;
  for (let i = 1; i < v.length; i++) if (Math.abs(v[i]) > Math.abs(v[k])) k = i;
  return v[k] < 0 ? v.map((x) => -x) : [...v];
}
export function difference(a: number[], b: number[]): number {
  let max = 0;
  for (let i = 0; i < a.length; i++) max = Math.max(max, Math.abs(a[i] - b[i]));
  return max;
}
export function deflate(m: number[][], value: number, v: number[]): void {
  for (let i = 0; i < m.length; i++) {
    for (let j = 0; j < m.length; j++) m[i][j] -= value * v[i] * v[j];
  }
}
export function inverseDeterminant(m: number[][]) {
  const n = m.length;
  const unit = identity(n);
  const augmented = m.map((row, i) => [...row, ...unit[i]]);
  let determinant = 1;
  for (let k = 0; k < n; k++) {
    const pivot = augmented[k][k];
    determinant *= pivot;
    for (let h = 0; h < 2 * n; h++) augmented[k][h] /= pivot;
    for (let i = 0; i < n; i++) {
      if (i !== k) {
        const c = augmented[i][k];
        for (let h = 0; h < 2 * n; h++) augmented[i][h] -= c * augmented[k][h];
      }
    }
  }
  return { inverse: augmented.map((row) => row.slice(n)), determinant };
}

import * as matrix from './matrix.ts';
import type { Scaling } from './dataset.ts';
export function standardize(
  values: (number | null)[],
  means: number[],
  scales: number[],
): number[] {
  return values.map((v, j) => (v === null ? 0 : (v - means[j]) / scales[j]));
}
export function prepare(rows: number[][], scaling: Scaling) {
  const p = rows[0].length;
  const n = rows.length;
  const means: number[] = [];
  for (let j = 0; j < p; j++) {
    let total = 0;
    for (const row of rows) total += row[j];
    means.push(total / n);
  }
  const covariance = matrix.zeros(p);
  for (let j = 0; j < p; j++) {
    for (let k = j; k < p; k++) {
      let total = 0;
      for (const row of rows) total += (row[j] - means[j]) * (row[k] - means[k]);
      covariance[j][k] = covariance[k][j] = total / (n - 1);
    }
  }
  const deviations = covariance.map((row, j) => Math.sqrt(row[j]));
  const correlation = covariance.map((row, j) =>
    row.map((v, k) => (j === k ? 1 : v / (deviations[j] * deviations[k]))),
  );
  const scales: number[] = scaling === 'covariance' ? Array(p).fill(1) : [...deviations];
  return {
    means,
    covariance,
    deviations,
    correlation,
    scales,
    matrix: scaling === 'covariance' ? covariance : correlation,
    standardized: rows.map((row) => standardize(row, means, scales)),
  };
}
export function scores(z: number[], vectors: number[][]): number[] {
  return vectors.map((v) => matrix.dot(z, v));
}
export function residuals(
  z: number[],
  scores: number[],
  vectors: number[][],
  retained: number,
): number[] {
  return z.map((v, j) => {
    let fitted = 0;
    for (let k = 0; k < retained; k++) fitted += scores[k] * vectors[k][j];
    return v - fitted;
  });
}
export function tSquared(scores: number[], values: number[], retained: number): number {
  let total = 0;
  for (let k = 0; k < retained; k++) total += (scores[k] * scores[k]) / values[k];
  return total;
}

export interface Cell {
  row: number;
  column: number;
}
export function grid(width: number, height: number): string[][] {
  return Array.from({ length: height }, () => Array(width).fill(' '));
}
export function frame(rows: string[][]): string[] {
  const border = '+' + '-'.repeat(rows[0].length) + '+';
  return [border, ...rows.map((row) => '|' + row.join('') + '|'), border];
}
export function biplotCell(
  x: number,
  y: number,
  mx: number,
  my: number,
  width: number,
  height: number,
): Cell {
  return {
    column: Math.min(Math.floor(((x + mx) / (2 * mx)) * width), width - 1),
    row: Math.min(Math.floor(((my - y) / (2 * my)) * height), height - 1),
  };
}
export function diagnosticCell(
  t2: number,
  spe: number,
  mx: number,
  my: number,
  width: number,
  height: number,
): Cell {
  return {
    column: Math.min(Math.floor((t2 / mx) * width), width - 1),
    row: height - 1 - Math.min(Math.floor((spe / my) * height), height - 1),
  };
}
export function shaft(origin: Cell, tip: Cell): (Cell & { character: string })[] {
  const dc = tip.column - origin.column;
  const dr = tip.row - origin.row;
  const steps = Math.max(Math.abs(dc), Math.abs(dr));
  const character =
    2 * Math.abs(dr) <= Math.abs(dc)
      ? '-'
      : 2 * Math.abs(dc) <= Math.abs(dr)
        ? '|'
        : dc * dr < 0
          ? '/'
          : '\\';
  const cells: (Cell & { character: string })[] = [];
  for (let s = 1; s < steps; s++) {
    cells.push({
      column:
        origin.column + Math.sign(dc) * Math.floor((2 * s * Math.abs(dc) + steps) / (2 * steps)),
      row: origin.row + Math.sign(dr) * Math.floor((2 * s * Math.abs(dr) + steps) / (2 * steps)),
      character,
    });
  }
  return cells;
}
export function scree(width: number, bar: number, broken: number, kaiser: number): string {
  let text = '';
  for (let p = 1; p <= width; p++) {
    text += p === broken ? 'o' : p === kaiser ? ':' : p <= bar ? '#' : ' ';
  }
  return text;
}
